import { PrismaClient } from '@prisma/client';
import { MONETIZATION_FEATURES, MEMBERSHIP_PRICING, MembershipStatus, MembershipType } from '../config/features.js';
import { createRequire } from 'node:module';

const prisma = new PrismaClient();
const require = createRequire(import.meta.url);
type StripeEvent = { type: string; data: { object: unknown } };
type StripeCheckoutSession = any;
type StripePaymentIntent = any;

let stripeClient: any | null = null;
function getStripeClient() {
  if (stripeClient) return stripeClient;
  try {
    const StripeCtor = require('stripe');
    stripeClient = new StripeCtor(process.env.STRIPE_SECRET_KEY!, {
      apiVersion: '2024-11-20.acacia',
    });
    return stripeClient;
  } catch {
    throw new Error('Stripe SDK is not installed. Run pnpm add stripe.');
  }
}

export interface MembershipData {
  userId: string;
  type: MembershipType;
  stripeCustomerId?: string;
  stripeCheckoutSessionId?: string;
}

export interface CreateMembershipResult {
  success: boolean;
  membership?: { id: string; userId: string; type: string; status: string };
  error?: string;
}

export class MembershipService {
  static async createMembership(data: MembershipData): Promise<CreateMembershipResult> {
    if (!MONETIZATION_FEATURES.MEMBERSHIP_PURCHASE_ENABLED) {
      return { success: false, error: 'Membership purchases are not enabled' };
    }

    try {
      // Check if user already has an active membership
      const existingMembership = await prisma.membership.findUnique({
        where: { userId: data.userId },
      });

      if (existingMembership && existingMembership.status === 'active') {
        return { success: false, error: 'User already has an active membership' };
      }

      // Create new membership
      const membership = await prisma.membership.create({
        data: {
          userId: data.userId,
          stripeId: data.stripeCustomerId,
          type: data.type,
          status: 'active',
          purchasedAt: new Date(),
          // Lifetime memberships don't expire
          expiresAt: data.type === 'lifetime' ? null : new Date(Date.now() + 365 * 24 * 60 * 60 * 1000), // 1 year
        },
      });

      return { success: true, membership };
    } catch (error) {
      console.error('Failed to create membership:', error);
      return { success: false, error: 'Failed to create membership' };
    }
  }

  static async getUserMembership(userId: string) {
    try {
      const membership = await prisma.membership.findUnique({
        where: { userId },
        include: {
          user: {
            select: {
              displayName: true,
              email: true,
            },
          },
        },
      });

      if (!membership) {
        return null;
      }

      // Check if membership is expired
      if (membership.expiresAt && membership.expiresAt < new Date()) {
        await this.updateMembershipStatus(membership.id, 'expired');
        return { ...membership, status: 'expired' };
      }

      return membership;
    } catch (error) {
      console.error('Failed to get user membership:', error);
      throw new Error('Failed to retrieve membership');
    }
  }

  static async updateMembershipStatus(membershipId: string, status: MembershipStatus) {
    try {
      await prisma.membership.update({
        where: { id: membershipId },
        data: { 
          status,
          updatedAt: new Date(),
        },
      });
    } catch (error) {
      console.error('Failed to update membership status:', error);
      throw new Error('Failed to update membership status');
    }
  }

  static async createStripeCheckoutSession(userId: string, userEmail: string) {
    if (!MONETIZATION_FEATURES.MEMBERSHIP_PURCHASE_ENABLED) {
      throw new Error('Membership purchases are not enabled');
    }

    try {
      // Get or create Stripe customer
      let customerId: string;
      const existingMembership = await prisma.membership.findUnique({
        where: { userId },
      });

      if (existingMembership?.stripeId) {
        customerId = existingMembership.stripeId;
      } else {
        const stripe = getStripeClient();
        const customer = await stripe.customers.create({
          email: userEmail,
          metadata: {
            userId,
          },
        });
        customerId = customer.id;
      }

      // Create checkout session
      const stripe = getStripeClient();
      const session = await stripe.checkout.sessions.create({
        customer: customerId,
        payment_method_types: ['card'],
        line_items: [
          {
            price_data: {
              currency: MEMBERSHIP_PRICING.LIFETIME.currency,
              product_data: {
                name: MEMBERSHIP_PRICING.LIFETIME.name,
                description: MEMBERSHIP_PRICING.LIFETIME.description,
              },
              unit_amount: MEMBERSHIP_PRICING.LIFETIME.amount,
            },
            quantity: 1,
          },
        ],
        mode: 'payment',
        success_url: `${process.env.STRIPE_SUCCESS_URL}?session_id={CHECKOUT_SESSION_ID}`,
        cancel_url: process.env.STRIPE_CANCEL_URL!,
        metadata: {
          userId,
          membershipType: 'lifetime',
        },
        allow_promotion_codes: false,
        billing_address_collection: 'auto',
      });

      return { success: true, sessionId: session.id, url: session.url };
    } catch (error) {
      console.error('Failed to create Stripe checkout session:', error);
      return { success: false, error: 'Failed to create checkout session' };
    }
  }

  static async handleWebhookEvent(event: StripeEvent) {
    switch (event.type) {
      case 'checkout.session.completed':
        return this.handleCheckoutSessionCompleted(event.data.object as StripeCheckoutSession);
      
      case 'payment_intent.succeeded':
        return this.handlePaymentIntentSucceeded(event.data.object as StripePaymentIntent);
      
      default:
        console.log(`Unhandled webhook event type: ${event.type}`);
        return { success: true, message: 'Event acknowledged' };
    }
  }

  private static async handleCheckoutSessionCompleted(session: StripeCheckoutSession) {
    try {
      const userId = session.metadata?.userId;
      const membershipType = session.metadata?.membershipType;
      const customerId = session.customer as string;

      if (!userId || !membershipType) {
        console.error('Missing required metadata in checkout session');
        return { success: false, error: 'Missing required metadata' };
      }

      // Create or update membership
      const result = await this.createMembership({
        userId,
        type: membershipType as MembershipType,
        stripeCustomerId: customerId,
        stripeCheckoutSessionId: session.id,
      });

      if (result.success) {
        console.log(`Membership created for user ${userId}`);
        await this.recordMembershipRevenue(session);
        return { success: true, membership: result.membership };
      } else {
        console.error('Failed to create membership from webhook:', result.error);
        return { success: false, error: result.error };
      }
    } catch (error) {
      console.error('Error handling checkout session completed:', error);
      return { success: false, error: 'Webhook processing failed' };
    }
  }

  private static async recordMembershipRevenue(session: StripeCheckoutSession): Promise<void> {
    const userId = session.metadata?.userId;
    const amountTotal = session.amount_total;
    if (!userId || amountTotal == null) return;

    const externalRef = session.id;
    const existing = await prisma.balanceTransaction.findUnique({
      where: { externalRef },
    });
    if (existing) return;

    await prisma.balanceTransaction.create({
      data: {
        id: `mem_${externalRef}`,
        userId,
        amountCents: amountTotal,
        type: 'MEMBERSHIP_PURCHASE',
        externalRef,
        metaJson: { stripeSessionId: session.id },
      },
    });
  }

  private static async handlePaymentIntentSucceeded(paymentIntent: StripePaymentIntent) {
    try {
      // Payment intents are handled primarily by checkout.session.completed
      // This is mainly for logging and additional processing if needed
      console.log(`Payment intent succeeded: ${paymentIntent.id}`);
      return { success: true, message: 'Payment intent processed' };
    } catch (error) {
      console.error('Error handling payment intent succeeded:', error);
      return { success: false, error: 'Payment intent processing failed' };
    }
  }

  static async getMembershipAnalytics() {
    try {
      const totalMemberships = await prisma.membership.count();
      const activeMemberships = await prisma.membership.count({
        where: { status: 'active' },
      });
      
      const lifetimeMemberships = await prisma.membership.count({
        where: { type: 'lifetime' },
      });

      const recentMemberships = await prisma.membership.findMany({
        take: 10,
        orderBy: { purchasedAt: 'desc' },
        include: {
          user: {
            select: {
              displayName: true,
              email: true,
            },
          },
        },
      });

      const totalRevenue = await prisma.balanceTransaction.aggregate({
        where: {
          type: 'MEMBERSHIP_PURCHASE',
        },
        _sum: {
          amountCents: true,
        },
      });

      return {
        totalMemberships,
        activeMemberships,
        lifetimeMemberships,
        totalRevenue: totalRevenue._sum.amountCents || 0,
        recentMemberships,
      };
    } catch (error) {
      console.error('Failed to get membership analytics:', error);
      throw new Error('Failed to retrieve membership analytics');
    }
  }
}

import express from "express";
import { requireAuth } from "./RequireAuth.js";
import { requireAdmin } from "./AdminMiddleware.js";
import { AdminService } from "./AdminService.js";
import { UserRole } from "@prisma/client";
import { RecoveryService } from "../recovery/RecoveryService.js";
import { toPublicUser } from "./PublicUser.js";

const router = express.Router();

router.use(requireAuth, requireAdmin); // Protect all routes

// GET /api/admin/users
router.get("/users", async (req, res) => {
  try {
    const page = parseInt(String(req.query.page) || "1");
    const limit = parseInt(String(req.query.limit) || "20");
    
    const result = await AdminService.getUsers(page, limit);
    res.json({
      users: result.users.map((item) => ({
        ...toPublicUser(item.user),
        stats: item.stats,
      })),
      total: result.total,
    });
  } catch (err: any) {
    res.status(500).json({ error: err.message });
  }
});

// POST /api/admin/users
router.post("/users", async (req, res) => {
  try {
    const { email, password, displayName, username } = req.body ?? {};
    if (!email || !password) {
      res.status(400).json({ error: "Email and password are required" });
      return;
    }

    const user = await AdminService.createAdminUser({ email, password, displayName, username });
    res.status(201).json(toPublicUser(user));
  } catch (err: any) {
    const message = err?.message ?? "Unable to create admin user";
    if (
      message === "Email already registered" ||
      message === "Username already taken" ||
      String(message).startsWith("Username must be at least")
    ) {
      res.status(400).json({ error: message });
      return;
    }
    res.status(500).json({ error: message });
  }
});

// PATCH /api/admin/users/:id/promote
router.patch("/users/:id/promote", async (req, res) => {
  try {
    const user = await AdminService.promoteUserToAdmin(req.params.id);
    res.json(toPublicUser(user));
  } catch (err: any) {
    if (err.code === "P2025") {
      res.status(404).json({ error: "User not found" });
      return;
    }
    res.status(500).json({ error: err.message });
  }
});

// POST /api/admin/users/:id/ban
router.post("/users/:id/ban", async (req, res) => {
  try {
    const user = await AdminService.banUser(req.params.id);
    res.json(toPublicUser(user));
  } catch (err: any) {
      if (err.code === 'P2025') { // Prisma record not found
          res.status(404).json({ error: "User not found" });
      } else {
        res.status(500).json({ error: err.message });
      }
  }
});

// POST /api/admin/users/:id/unban
router.post("/users/:id/unban", async (req, res) => {
  try {
    const user = await AdminService.unbanUser(req.params.id);
    res.json(toPublicUser(user));
  } catch (err: any) {
      if (err.code === 'P2025') {
          res.status(404).json({ error: "User not found" });
      } else {
        res.status(500).json({ error: err.message });
      }
  }
});

// POST /api/admin/users/:id/delete
router.post("/users/:id/delete", async (req, res) => {
  try {
    const user = await AdminService.softDeleteUser(req.params.id);
    res.json(toPublicUser(user));
  } catch (err: any) {
    if (err.code === "P2025") {
      res.status(404).json({ error: "User not found" });
    } else {
      res.status(500).json({ error: err.message });
    }
  }
});

// POST /api/admin/users/:id/restore
router.post("/users/:id/restore", async (req, res) => {
  try {
    const user = await AdminService.restoreUser(req.params.id);
    res.json(toPublicUser(user));
  } catch (err: any) {
    if (err.code === "P2025") {
      res.status(404).json({ error: "User not found" });
    } else {
      res.status(500).json({ error: err.message });
    }
  }
});


// PATCH /api/admin/users/:id/role
router.patch("/users/:id/role", async (req, res) => {
    try {
        const { role } = req.body;
        if (!Object.values(UserRole).includes(role)) {
             res.status(400).json({ error: "Invalid role. Must be one of: " + Object.values(UserRole).join(", ") });
             return;
        }

        const user = await AdminService.setRole(req.params.id, role);
        res.json(toPublicUser(user));
    } catch (err: any) {
         if (err.code === 'P2025') {
          res.status(404).json({ error: "User not found" });
      } else {
        res.status(500).json({ error: err.message });
      }
    }
});

// GET /api/admin/economy/balances
router.get("/economy/balances", async (req, res) => {
  try {
    const result = await AdminService.getBalances({
      page: parseInt(String(req.query.page) || "1"),
      limit: parseInt(String(req.query.limit) || "20"),
      tableId: req.query.tableId as string,
      userId: req.query.userId as string,
      status: req.query.status as string,
    });
    res.json(result);
  } catch (err: any) {
    res.status(500).json({ error: err.message });
  }
});

// GET /api/admin/economy/transactions
router.get("/economy/transactions", async (req, res) => {
  try {
    const result = await AdminService.getTransactions({
      page: parseInt(String(req.query.page) || "1"),
      limit: parseInt(String(req.query.limit) || "20"),
      tableId: req.query.tableId as string,
      userId: req.query.userId as string,
      handId: req.query.handId as string,
    });
    res.json(result);
  } catch (err: any) {
    res.status(500).json({ error: err.message });
  }
});

// POST /api/admin/economy/recovery
router.post("/economy/recovery", async (req, res) => {
  try {
    const thresholdHours = parseInt(String(req.query.thresholdHours) || "2");
    const thresholdMs = thresholdHours * 60 * 60 * 1000;
    
    const result = await RecoveryService.reconcileAbandonedBalances(thresholdMs);
    res.json(result);
  } catch (err: any) {
    res.status(500).json({ error: err.message });
  }
});

export const adminRouter = router;

import { getPrisma } from "@poker-champ/db";
import type { User } from "@prisma/client";
import { UserRole } from "@prisma/client";
import { matchMaker } from "@colyseus/core";
import { sessionEvents } from "./SessionEvents.js";
import { AuthService } from "./AuthService.js";

type AdminUserStats = {
  lastOnlineAt: Date | null;
  totalOnlineHours: number;
  totalSpendCents: number;
  totalLostCents: number;
  totalBuyInCents: number;
  totalCashOutCents: number;
  totalTournamentEntryCents: number;
  totalTournamentPayoutCents: number;
};

type AdminUserListItem = {
  user: User;
  stats: AdminUserStats;
};

export class AdminService {
  static async createAdminUser(input: {
    email: string;
    password: string;
    displayName?: string;
    username?: string;
  }): Promise<User> {
    const prisma = getPrisma();
    const { user } = await AuthService.register(
      input.email,
      input.password,
      input.displayName || "Admin",
      input.username,
    );

    await AuthService.revokeUserSessions(user.id);
    return prisma.user.update({
      where: { id: user.id },
      data: { role: "ADMIN" },
    });
  }

  static async promoteUserToAdmin(userId: string): Promise<User> {
    const prisma = getPrisma();
    return prisma.user.update({
      where: { id: userId },
      data: { role: "ADMIN" },
    });
  }

  static async getUsers(page: number = 1, limit: number = 20): Promise<{ users: AdminUserListItem[], total: number }> {
    const prisma = getPrisma();
    const skip = (page - 1) * limit;

    const [users, total] = await Promise.all([
      prisma.user.findMany({
        skip,
        take: limit,
        orderBy: { createdAt: "desc" },
         // Exclude sensitive fields if necessary, though passwordHash is safer to exclude in Controller layer
         // But for simplicity sending full object for now
      }),
      prisma.user.count()
    ]);

    if (users.length === 0) {
      return { users: [], total };
    }

    const userIds = users.map((u) => u.id);

    const [txByType, sessions, sessionLastSeen] = await Promise.all([
      prisma.balanceTransaction.groupBy({
        by: ["userId", "type"],
        where: { userId: { in: userIds } },
        _sum: { amountCents: true },
      }),
      prisma.userSession.findMany({
        where: { userId: { in: userIds } },
        select: { userId: true, createdAt: true, lastUsedAt: true },
      }),
      prisma.userSession.groupBy({
        by: ["userId"],
        where: { userId: { in: userIds } },
        _max: { lastUsedAt: true, createdAt: true },
      }),
    ]);

    const [seatSessions, seatLastSeen] = await Promise.all([
      prisma.tableSeatSession.findMany({
        where: { userId: { in: userIds } },
        select: { userId: true, createdAt: true, lastSeenAt: true, disconnectAt: true },
      }),
      prisma.tableSeatSession.groupBy({
        by: ["userId"],
        where: { userId: { in: userIds } },
        _max: { lastSeenAt: true, createdAt: true, disconnectAt: true },
      }),
    ]);

    const txSumsByUser = new Map<string, Record<string, number>>();
    for (const row of txByType) {
      const byType = txSumsByUser.get(row.userId) ?? {};
      byType[row.type] = row._sum.amountCents ?? 0;
      txSumsByUser.set(row.userId, byType);
    }

    const onlineMsByUser = new Map<string, number>();
    for (const s of sessions) {
      const start = s.createdAt.getTime();
      const end = (s.lastUsedAt ?? s.createdAt).getTime();
      const ms = Math.max(0, end - start);
      onlineMsByUser.set(s.userId, (onlineMsByUser.get(s.userId) ?? 0) + ms);
    }
    for (const s of seatSessions) {
      const start = s.createdAt.getTime();
      const end = (s.disconnectAt ?? s.lastSeenAt ?? s.createdAt).getTime();
      const ms = Math.max(0, end - start);
      onlineMsByUser.set(s.userId, (onlineMsByUser.get(s.userId) ?? 0) + ms);
    }

    const lastOnlineByUser = new Map<string, Date | null>();
    for (const s of sessionLastSeen) {
      const candidate = s._max.lastUsedAt ?? s._max.createdAt ?? null;
      if (candidate) lastOnlineByUser.set(s.userId, candidate);
    }
    for (const s of seatLastSeen) {
      const candidate = s._max.lastSeenAt ?? s._max.disconnectAt ?? s._max.createdAt ?? null;
      const current = lastOnlineByUser.get(s.userId);
      if (!candidate) continue;
      if (!current || candidate.getTime() > current.getTime()) {
        lastOnlineByUser.set(s.userId, candidate);
      }
    }

    const enriched = users.map((user) => {
      const tx = txSumsByUser.get(user.id) ?? {};
      const totalBuyInCents = tx.BUYIN ?? 0;
      const totalCashOutCents = tx.CASHOUT ?? 0;
      const totalTournamentEntryCents = tx.TOURNAMENT_ENTRY ?? 0;
      const totalTournamentPayoutCents = tx.TOURNAMENT_PAYOUT ?? 0;
      const totalSpendCents = totalBuyInCents + totalTournamentEntryCents;
      const totalLostCents =
        Math.max(0, totalBuyInCents - totalCashOutCents) +
        Math.max(0, totalTournamentEntryCents - totalTournamentPayoutCents);

      return {
        user,
        stats: {
          lastOnlineAt: lastOnlineByUser.get(user.id) ?? null,
          totalOnlineHours: Math.round(((onlineMsByUser.get(user.id) ?? 0) / 3_600_000) * 10) / 10,
          totalSpendCents,
          totalLostCents,
          totalBuyInCents,
          totalCashOutCents,
          totalTournamentEntryCents,
          totalTournamentPayoutCents,
        },
      };
    });

    return { users: enriched, total };
  }

  static async banUser(userId: string): Promise<User> {
    const prisma = getPrisma();
    const user = await prisma.user.update({
      where: { id: userId },
      data: { isBanned: true }
    });

    await prisma.userSession.deleteMany({ where: { userId } });
    sessionEvents.emit("user.banned", { userId });
    await this.kickUserFromAllPokerRooms(userId);

    return user;
  }

  static async unbanUser(userId: string): Promise<User> {
    const prisma = getPrisma();
    return await prisma.user.update({
      where: { id: userId },
      data: { isBanned: false }
    });
  }

  static async softDeleteUser(userId: string): Promise<User> {
    const prisma = getPrisma();
    const user = await prisma.user.update({
      where: { id: userId },
      data: { deletedAt: new Date() },
    });

    await prisma.userSession.deleteMany({ where: { userId } });
    sessionEvents.emit("user.banned", { userId });
    await this.kickUserFromAllPokerRooms(userId);

    return user;
  }

  static async restoreUser(userId: string): Promise<User> {
    const prisma = getPrisma();
    return prisma.user.update({
      where: { id: userId },
      data: { deletedAt: null },
    });
  }

  static async setRole(userId: string, role: UserRole): Promise<User> {
      const prisma = getPrisma();
      return await prisma.user.update({
          where: { id: userId },
          data: { role }
      });
  }

  static async getBalances(params: {
    page?: number;
    limit?: number;
    tableId?: string;
    userId?: string;
    status?: string;
  }): Promise<{ items: any[]; total: number }> {
    const prisma = getPrisma();
    const page = params.page || 1;
    const limit = params.limit || 20;
    const skip = (page - 1) * limit;

    const where: any = {};
    if (params.tableId) where.tableId = params.tableId;
    if (params.userId) where.userId = params.userId;
    if (params.status) where.status = params.status;

    const [items, total] = await Promise.all([
      prisma.playerBalance.findMany({
        where,
        skip,
        take: limit,
        orderBy: { updatedAt: "desc" },
      }),
      prisma.playerBalance.count({ where }),
    ]);

    return { items, total };
  }

  static async getTransactions(params: {
    page?: number;
    limit?: number;
    tableId?: string;
    userId?: string;
    handId?: string;
  }): Promise<{ items: any[]; total: number }> {
    const prisma = getPrisma();
    const page = params.page || 1;
    const limit = params.limit || 20;
    const skip = (page - 1) * limit;

    const where: any = {};
    if (params.tableId) where.tableId = params.tableId;
    if (params.userId) where.userId = params.userId;
    if (params.handId) where.handId = params.handId;

    const [items, total] = await Promise.all([
      prisma.balanceTransaction.findMany({
        where,
        skip,
        take: limit,
        orderBy: { createdAt: "desc" },
      }),
      prisma.balanceTransaction.count({ where }),
    ]);

    return { items, total };
  }

  private static async kickUserFromAllPokerRooms(userId: string): Promise<void> {
    const rooms = await matchMaker.query({ name: "poker" });
    await Promise.allSettled(
      rooms.map(async (room) => {
        const roomId = (room as any)?.roomId;
        if (!roomId) return;
        await matchMaker.remoteRoomCall<any>(roomId, "kickUserByAdmin" as any, [userId, "BANNED"], 5000);
      }),
    );
  }
}

import express from "express";
import { AuthService } from "./AuthService.js";
import { requireAuth } from "./RequireAuth.js";
import { openApiSpec } from "../../http/openapi.js";
import { toPublicUser } from "./PublicUser.js";

const router = express.Router();

router.post("/register", async (req, res) => {
  try {
    const { email, password, displayName, username } = req.body;

    if (!email || !password) {
      res.status(400).json({ error: "Email and password are required" });
      return;
    }

    const result = await AuthService.register(email, password, displayName || "Player", username);
    res.json({ token: result.token, user: toPublicUser(result.user) });
  } catch (err: any) {
    if (err?.message === "Email already registered" || err?.message === "Username already taken" || String(err?.message ?? "").startsWith("Username must be at least")) {
      res.status(400).json({ error: err.message });
      return;
    }
    res.status(500).json({ error: err?.message ?? "Registration failed" });
  }
});

router.post("/login", async (req, res) => {
  try {
    const { email, password } = req.body;

    if (!email || !password) {
      res.status(400).json({ error: "Email and password are required" });
      return;
    }

    const result = await AuthService.login(email, password);
    res.json({ token: result.token, user: toPublicUser(result.user) });
  } catch (err: any) {
    const message = err?.message ?? "Login failed";
    if (message === "Invalid credentials" || message === "Account is suspended") {
      res.status(401).json({ error: message });
      return;
    }
    res.status(500).json({ error: message });
  }
});

router.get("/me", requireAuth, async (req, res) => {
  res.json({ user: toPublicUser(req.user!), openapiVersion: openApiSpec.info.version });
});

router.post("/logout", requireAuth, async (req, res) => {
  try {
    const authHeader = req.headers.authorization as string;
    const token = authHeader.slice("Bearer ".length).trim();
    await AuthService.revokeSession(token);
    res.json({ success: true });
  } catch (err: any) {
    res.status(400).json({ error: err.message ?? "Unable to log out" });
  }
});

router.post("/logout-all", requireAuth, async (req, res) => {
  try {
    await AuthService.revokeUserSessions(req.user!.id);
    res.json({ success: true });
  } catch (err: any) {
    res.status(400).json({ error: err.message ?? "Unable to log out all sessions" });
  }
});

export const authRouter = router;

import { nanoid } from "nanoid";
import bcrypt from "bcryptjs";
import { User } from "@prisma/client";
import { getPrisma } from "@poker-champ/db";
import { logger } from "../../lib/logger.js";

type AuthToken = string;
const DEFAULT_SESSION_TTL_DAYS = 14;
const MIN_USERNAME_LEN = 3;
const MAX_USERNAME_LEN = 24;
const STARTING_BANKROLL_CENTS = 1_000_000;

export class AuthService {
  static async register(
    email: string,
    password: string,
    displayName: string,
    usernameInput?: string,
  ): Promise<{ token: AuthToken; user: User }> {
    const prisma = getPrisma();

    const normalizedEmail = this.normalizeEmail(email);
    const existing = await prisma.user.findUnique({ where: { email: normalizedEmail } });
    if (existing) {
      throw new Error("Email already registered");
    }

    const handle = await this.allocateUsername(normalizedEmail, usernameInput);
    const passwordHash = await bcrypt.hash(password, 12);

    const user = await prisma.user.create({
      data: {
        email: normalizedEmail,
        username: handle.username,
        usernameNormalized: handle.usernameNormalized,
        passwordHash,
        displayName,
        role: "USER",
        bankrollCents: STARTING_BANKROLL_CENTS,
      },
    });

    const token = await this.createSession(user.id);
    return { token, user };
  }

  static async login(email: string, password: string): Promise<{ token: AuthToken; user: User }> {
    const prisma = getPrisma();
    const normalizedEmail = this.normalizeEmail(email);

    const user = await prisma.user.findUnique({ where: { email: normalizedEmail } });
    if (!user) {
      throw new Error("Invalid credentials");
    }

    if (user.isBanned || user.deletedAt) {
      throw new Error("Account is suspended");
    }

    const isValid = await bcrypt.compare(password, user.passwordHash);
    if (!isValid) {
      throw new Error("Invalid credentials");
    }

    const hydrated = await this.ensureUserHandle(user);
    await this.revokeUserSessions(hydrated.id);
    const token = await this.createSession(user.id);
    return { token, user: hydrated };
  }

  static async validateSession(token: string): Promise<User | null> {
    const prisma = getPrisma();
    try {
      const session = await prisma.userSession.findUnique({
        where: { id: token },
        include: { user: true },
      });

      if (!session) return null;

      if (session.expiresAt < new Date()) {
        await prisma.userSession.delete({ where: { id: token } });
        return null;
      }

      if (session.user.isBanned || session.user.deletedAt) return null;

      const now = new Date();
      await prisma.userSession.update({
        where: { id: token },
        data: {
          lastUsedAt: now,
          expiresAt: new Date(now.getTime() + this.getSessionTtlMs()),
        },
      });

      return this.ensureUserHandle(session.user);
    } catch (err: any) {
      logger.error({ err }, "validateSession failed due to backend error");
      const backendErr = new Error("Auth backend unavailable");
      (backendErr as any).code = "AUTH_BACKEND_UNAVAILABLE";
      throw backendErr;
    }
  }

  static async revokeSession(token: string): Promise<void> {
    const prisma = getPrisma();
    await prisma.userSession.deleteMany({ where: { id: token } });
  }

  static async revokeUserSessions(userId: string): Promise<void> {
    const prisma = getPrisma();
    await prisma.userSession.deleteMany({ where: { userId } });
  }

  private static async createSession(userId: string): Promise<string> {
    const prisma = getPrisma();
    const token = nanoid(32);
    const now = new Date();
    const expiresAt = new Date(now.getTime() + this.getSessionTtlMs());

    await prisma.userSession.create({
      data: {
        id: token,
        userId,
        createdAt: now,
        lastUsedAt: now,
        expiresAt,
      },
    });

    return token;
  }

  private static normalizeEmail(email: string) {
    return email.trim().toLowerCase();
  }

  private static normalizeUsername(raw: string): string {
    const cleaned = raw
      .trim()
      .replace(/\s+/g, "_")
      .replace(/[^A-Za-z0-9_]/g, "")
      .toLowerCase();
    return cleaned.slice(0, MAX_USERNAME_LEN);
  }

  private static fallbackUsernameFromEmail(email: string): string {
    const prefix = email.split("@")[0] ?? "player";
    const normalized = this.normalizeUsername(prefix);
    if (normalized.length >= MIN_USERNAME_LEN) return normalized;
    return "player";
  }

  private static async allocateUsername(email: string, usernameInput?: string) {
    const prisma = getPrisma();
    const requested = typeof usernameInput === "string" ? this.normalizeUsername(usernameInput) : "";
    const base = requested || this.fallbackUsernameFromEmail(email);

    if (requested) {
      if (requested.length < MIN_USERNAME_LEN) {
        throw new Error(`Username must be at least ${MIN_USERNAME_LEN} characters`);
      }
      const existing = await prisma.user.findFirst({ where: { usernameNormalized: requested } });
      if (existing) {
        throw new Error("Username already taken");
      }
      return { username: requested, usernameNormalized: requested };
    }

    for (let attempt = 0; attempt < 50; attempt++) {
      const suffix = attempt === 0 ? "" : `_${nanoid(4).toLowerCase()}`;
      const candidate = `${base}${suffix}`.slice(0, MAX_USERNAME_LEN);
      const normalized = this.normalizeUsername(candidate);
      if (normalized.length < MIN_USERNAME_LEN) continue;

      const existing = await prisma.user.findFirst({ where: { usernameNormalized: normalized } });
      if (!existing) {
        return { username: normalized, usernameNormalized: normalized };
      }
    }

    throw new Error("Could not allocate username");
  }

  private static async ensureUserHandle(user: User): Promise<User> {
    if (user.username && user.usernameNormalized) return user;

    const prisma = getPrisma();
    const handle = await this.allocateUsername(user.email, user.username ?? undefined);
    return prisma.user.update({
      where: { id: user.id },
      data: {
        username: handle.username,
        usernameNormalized: handle.usernameNormalized,
      },
    });
  }

  private static getSessionTtlMs() {
    const parsed = Number.parseInt(process.env.SESSION_TTL_DAYS ?? "", 10);
    const days = Number.isFinite(parsed) && parsed > 0 ? parsed : DEFAULT_SESSION_TTL_DAYS;
    return days * 24 * 60 * 60 * 1000;
  }
}

import type { NextFunction, Request, Response } from "express";
import { AuthService } from "./AuthService.js";

function parseBearerToken(req: Request): string | null {
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    return null;
  }
  const token = authHeader.slice("Bearer ".length).trim();
  return token.length > 0 ? token : null;
}

export async function requireAuth(req: Request, res: Response, next: NextFunction) {
  try {
    const token = parseBearerToken(req);
    if (!token) {
      res.status(401).json({ error: "Missing or invalid Authorization header" });
      return;
    }

    const user = await AuthService.validateSession(token);
    if (!user) {
      res.status(401).json({ error: "Invalid or expired session" });
      return;
    }

    req.user = user;
    next();
  } catch (err: any) {
    if (err?.code === "AUTH_BACKEND_UNAVAILABLE") {
      res.status(503).json({ error: "Auth service unavailable", code: "AUTH_BACKEND_UNAVAILABLE" });
      return;
    }
    res.status(500).json({ error: "Internal Server Error" });
  }
}

import { getPrisma } from "@poker-champ/db";

type SeatSessionState = "SEATED_ACTIVE" | "SEATED_SITTING_OUT" | "LEFT";

type UpsertSeatInput = {
  tableId: string;
  userId: string;
  seat: number;
  stackCentsSnapshot: number;
  buyInCents: number;
  handIdSnapshot?: string;
  schemaVersion?: number;
};

type ReapParams = {
  tableId: string;
  retentionHours: number;
  hardDeleteHours: number;
};

type SoftExpiredSeatSession = {
  id: string;
  tableId: string;
  userId: string;
  seat: number;
  stackCentsSnapshot: number;
  state: SeatSessionState;
  disconnectAt: Date | null;
};

type RestorableSeatSession = {
  id: string;
  tableId: string;
  userId: string;
  seat: number;
  stackCentsSnapshot: number;
  buyInCents: number;
  state: SeatSessionState;
  handIdSnapshot: string | null;
  schemaVersion: number;
  disconnectAt: Date | null;
  lastSeenAt: Date;
};

type SittingOutSessionTimestamp = {
  userId: string;
  disconnectAt: Date | null;
};

export class TableSeatSessionService {
  static async listRestorableSessionsForTable(params: {
    tableId: string;
    retentionHours: number;
  }): Promise<RestorableSeatSession[]> {
    const prisma = getPrisma() as any;
    const retentionHours = Math.max(1, Math.floor(params.retentionHours));
    const softCutoff = new Date(Date.now() - retentionHours * 60 * 60 * 1000);
    const rows: RestorableSeatSession[] = await prisma.tableSeatSession.findMany({
      where: {
        tableId: params.tableId,
        state: { in: ["SEATED_ACTIVE", "SEATED_SITTING_OUT"] },
        OR: [{ disconnectAt: null }, { disconnectAt: { gte: softCutoff } }],
      },
      orderBy: [{ seat: "asc" }, { updatedAt: "desc" }],
      select: {
        id: true,
        tableId: true,
        userId: true,
        seat: true,
        stackCentsSnapshot: true,
        buyInCents: true,
        state: true,
        handIdSnapshot: true,
        schemaVersion: true,
        disconnectAt: true,
        lastSeenAt: true,
      },
    });
    return rows;
  }

  static async markLeftBySessionId(params: {
    id: string;
  }): Promise<void> {
    const prisma = getPrisma() as any;
    await prisma.tableSeatSession.updateMany({
      where: { id: params.id },
      data: {
        state: "LEFT" as SeatSessionState,
        lastSeenAt: new Date(),
      },
    });
  }

  static async reapExpiredSessionsForTable(params: ReapParams): Promise<{
    softExpired: SoftExpiredSeatSession[];
    hardDeletedCount: number;
  }> {
    const prisma = getPrisma() as any;
    const now = Date.now();
    const retentionHours = Math.max(1, Math.floor(params.retentionHours));
    const hardDeleteHours = Math.max(retentionHours, Math.floor(params.hardDeleteHours));
    const softCutoff = new Date(now - retentionHours * 60 * 60 * 1000);
    const hardCutoff = new Date(now - hardDeleteHours * 60 * 60 * 1000);

    return prisma.$transaction(async (tx: any) => {
      const softExpired: SoftExpiredSeatSession[] = await tx.tableSeatSession.findMany({
        where: {
          tableId: params.tableId,
          state: "SEATED_SITTING_OUT",
          disconnectAt: { not: null, lte: softCutoff, gt: hardCutoff },
        },
        select: {
          id: true,
          tableId: true,
          userId: true,
          seat: true,
          stackCentsSnapshot: true,
          state: true,
          disconnectAt: true,
        },
      });

      if (softExpired.length > 0) {
        await tx.tableSeatSession.updateMany({
          where: { id: { in: softExpired.map((row) => row.id) } },
          data: {
            state: "LEFT",
            lastSeenAt: new Date(),
          },
        });
      }

      const hardDeleted = await tx.tableSeatSession.deleteMany({
        where: {
          tableId: params.tableId,
          state: { in: ["LEFT", "SEATED_SITTING_OUT"] },
          disconnectAt: { not: null, lte: hardCutoff },
        },
      });

      return {
        softExpired,
        hardDeletedCount: hardDeleted.count ?? 0,
      };
    });
  }

  static async findRejoinableSession(params: {
    tableId: string;
    userId: string;
  }): Promise<{
    tableId: string;
    userId: string;
    seat: number;
    stackCentsSnapshot: number;
    buyInCents: number;
    state: SeatSessionState;
  } | null> {
    const prisma = getPrisma() as any;
    const row = await prisma.tableSeatSession.findUnique({
      where: { tableId_userId: { tableId: params.tableId, userId: params.userId } },
      select: {
        tableId: true,
        userId: true,
        seat: true,
        stackCentsSnapshot: true,
        buyInCents: true,
        state: true,
      },
    });
    if (!row) return null;
    if (row.state === "LEFT") return null;
    return row;
  }

  static async upsertActiveSeat(input: UpsertSeatInput): Promise<void> {
    const prisma = getPrisma() as any;
    const now = new Date();
    const schemaVersion = input.schemaVersion ?? 1;

    await prisma.$transaction(async (tx: any) => {
      // Row-level lock on table rows to reduce double-seat races under concurrent joins.
      await tx.$queryRawUnsafe(
        "SELECT id FROM TableSeatSession WHERE tableId = ? FOR UPDATE",
        input.tableId,
      );

      const conflicting = await tx.tableSeatSession.findFirst({
        where: {
          tableId: input.tableId,
          seat: input.seat,
          state: { in: ["SEATED_ACTIVE", "SEATED_SITTING_OUT"] },
          userId: { not: input.userId },
        },
      });
      if (conflicting) {
        throw new Error("SEAT_CONFLICT");
      }

      await tx.tableSeatSession.upsert({
        where: { tableId_userId: { tableId: input.tableId, userId: input.userId } },
        create: {
          tableId: input.tableId,
          userId: input.userId,
          seat: input.seat,
          state: "SEATED_ACTIVE",
          stackCentsSnapshot: input.stackCentsSnapshot,
          buyInCents: input.buyInCents,
          handIdSnapshot: input.handIdSnapshot,
          disconnectAt: null,
          lastSeenAt: now,
          schemaVersion,
        },
        update: {
          seat: input.seat,
          state: "SEATED_ACTIVE",
          stackCentsSnapshot: input.stackCentsSnapshot,
          buyInCents: input.buyInCents,
          handIdSnapshot: input.handIdSnapshot,
          disconnectAt: null,
          lastSeenAt: now,
          schemaVersion,
        },
      });
    });
  }

  static async markSittingOut(params: {
    tableId: string;
    userId: string;
    stackCentsSnapshot?: number;
    handIdSnapshot?: string;
  }): Promise<void> {
    const prisma = getPrisma() as any;
    await prisma.tableSeatSession.updateMany({
      where: { tableId: params.tableId, userId: params.userId },
      data: {
        state: "SEATED_SITTING_OUT" as SeatSessionState,
        disconnectAt: new Date(),
        lastSeenAt: new Date(),
        ...(typeof params.stackCentsSnapshot === "number" ? { stackCentsSnapshot: params.stackCentsSnapshot } : {}),
        ...(params.handIdSnapshot ? { handIdSnapshot: params.handIdSnapshot } : {}),
      },
    });
  }

  static async markLeft(params: {
    tableId: string;
    userId: string;
    reason?: string;
    stackCentsSnapshot?: number;
    handIdSnapshot?: string;
  }): Promise<void> {
    const prisma = getPrisma() as any;
    await prisma.tableSeatSession.updateMany({
      where: { tableId: params.tableId, userId: params.userId },
      data: {
        state: "LEFT" as SeatSessionState,
        disconnectAt: null,
        lastSeenAt: new Date(),
        ...(typeof params.stackCentsSnapshot === "number" ? { stackCentsSnapshot: params.stackCentsSnapshot } : {}),
        ...(params.handIdSnapshot ? { handIdSnapshot: params.handIdSnapshot } : {}),
      },
    });
  }

  static async listSittingOutDisconnectTimesForUsers(params: {
    tableId: string;
    userIds: string[];
  }): Promise<SittingOutSessionTimestamp[]> {
    if (params.userIds.length === 0) return [];
    const prisma = getPrisma() as any;
    const rows: SittingOutSessionTimestamp[] = await prisma.tableSeatSession.findMany({
      where: {
        tableId: params.tableId,
        userId: { in: params.userIds },
        state: "SEATED_SITTING_OUT",
      },
      select: {
        userId: true,
        disconnectAt: true,
      },
    });
    return rows;
  }

  /** Mark all seat sessions for a table as LEFT. Used when table is deleted. */
  static async markAllLeftForTable(params: { tableId: string }): Promise<void> {
    const prisma = getPrisma() as any;
    await prisma.tableSeatSession.updateMany({
      where: { tableId: params.tableId, state: { in: ["SEATED_ACTIVE", "SEATED_SITTING_OUT"] } },
      data: { state: "LEFT" as SeatSessionState, lastSeenAt: new Date() },
    });
  }

  static async touchConnected(params: {
    tableId: string;
    userId: string;
    stackCentsSnapshot?: number;
    handIdSnapshot?: string;
  }): Promise<void> {
    const prisma = getPrisma() as any;
    await prisma.tableSeatSession.updateMany({
      where: { tableId: params.tableId, userId: params.userId },
      data: {
        state: "SEATED_ACTIVE" as SeatSessionState,
        disconnectAt: null,
        lastSeenAt: new Date(),
        ...(typeof params.stackCentsSnapshot === "number" ? { stackCentsSnapshot: params.stackCentsSnapshot } : {}),
        ...(params.handIdSnapshot ? { handIdSnapshot: params.handIdSnapshot } : {}),
      },
    });
  }
}

import express from "express";
import { matchMaker } from "@colyseus/core";
import { z } from "zod";
import { nanoid } from "nanoid";
import { requireAuth } from "../engine/auth/RequireAuth.js";
import { getPrisma } from "@poker-champ/db";
import { CashierService, TABLE_NAME_REQUIRED } from "../engine/economy/CashierService.js";
import { logger } from "../lib/logger.js";

const router = express.Router();

const BuyInSchema = z.object({
  tableId: z.string().min(1),
  amountCents: z.number().int().positive(),
  externalRef: z.string().min(1).optional(),
});

const CashOutSchema = z.object({
  tableId: z.string().min(1),
  amountCents: z.number().int().positive(),
  externalRef: z.string().min(1).optional(),
});

router.use(requireAuth);

router.get("/wallet", async (req, res) => {
  const prisma = getPrisma();
  const user = await prisma.user.findUniqueOrThrow({
    where: { id: req.user!.id },
    select: { bankrollCents: true },
  });
  res.json(user);
});

router.get("/transactions", async (req, res) => {
  const limit = Math.max(1, Math.min(100, Number(req.query.limit ?? 50)));
  const prisma = getPrisma();
  const items = await prisma.balanceTransaction.findMany({
    where: { userId: req.user!.id },
    orderBy: { createdAt: "desc" },
    take: limit,
  });
  res.json({ items });
});

router.post("/deposit", async (req, res) => {
  const DEPOSIT_CENTS = 100_000;
  const prisma = getPrisma();

  const updated = await prisma.$transaction(async (tx) => {
    const user = await tx.user.update({
      where: { id: req.user!.id },
      data: { bankrollCents: { increment: DEPOSIT_CENTS } },
      select: { bankrollCents: true },
    });

    await tx.balanceTransaction.create({
      data: {
        id: nanoid(),
        userId: req.user!.id,
        amountCents: DEPOSIT_CENTS,
        type: "DEPOSIT",
        externalRef: `deposit_${req.user!.id}_${Date.now()}_${nanoid(6)}`,
      },
    });

    return user;
  });

  res.json(updated);
});

router.post("/buy-in", async (req, res) => {
  const parsed = BuyInSchema.safeParse(req.body ?? {});
  if (!parsed.success) {
    res.status(400).json({ error: "Invalid buy-in payload", details: parsed.error.flatten() });
    return;
  }

  try {
    const rooms = (await matchMaker.query({ name: "poker" })) as {
      roomId?: string;
      metadata?: { tableId?: string; name?: string; creatorId?: string };
    }[];
    const room = rooms.find((r) => (r.metadata?.tableId ?? r.roomId) === parsed.data.tableId);
    const prisma = getPrisma();
    const tableRow = await prisma.pokerTable.findUnique({
      where: { id: parsed.data.tableId },
      select: { name: true, creatorId: true },
    });
    const tableName = room?.metadata?.name ?? tableRow?.name;
    if (!tableName || tableName.trim().length === 0) {
      res.status(409).json({ error: "Table metadata unavailable; cannot process buy-in." });
      return;
    }
    const tableMeta = {
      name: tableName,
      creatorId: room?.metadata?.creatorId ?? tableRow?.creatorId ?? undefined,
    };
    const rebuyRef =
      parsed.data.externalRef ?? `buyin_${parsed.data.tableId}_${req.user!.id}_${Date.now()}_${nanoid(6)}`;

    const result = await CashierService.processCashGameBuyIn({
      userId: req.user!.id,
      tableId: parsed.data.tableId,
      amountCents: parsed.data.amountCents,
      externalRef: rebuyRef,
      tableMeta,
    });
    const userId = req.user!.id;
    const { tableId, amountCents } = parsed.data;
    try {
      if (room?.roomId) {
        await matchMaker.remoteRoomCall(room.roomId, "applyRebuy", [userId, amountCents, rebuyRef]);
      }
    } catch (roomErr) {
      logger.error({ err: roomErr, tableId, userId }, "applyRebuy to room failed after buy-in");
      res.status(502).json({ error: "BUYIN_APPLIED_ROOM_SYNC_FAILED" });
      return;
    }
    res.json(result);
  } catch (err: any) {
    if (err?.message === "INSUFFICIENT_BANKROLL") {
      res.status(400).json({ error: err.message });
      return;
    }
    if (err?.message === TABLE_NAME_REQUIRED) {
      res.status(409).json({ error: "Table name metadata is required for buy-in." });
      return;
    }
    res.status(500).json({ error: err?.message ?? "Buy-in failed" });
  }
});

router.post("/cash-out", async (req, res) => {
  const parsed = CashOutSchema.safeParse(req.body ?? {});
  if (!parsed.success) {
    res.status(400).json({ error: "Invalid cash-out payload", details: parsed.error.flatten() });
    return;
  }

  try {
    const rooms = (await matchMaker.query({ name: "poker" })) as {
      roomId?: string;
      metadata?: { tableId?: string; name?: string; creatorId?: string };
    }[];
    const room = rooms.find((r) => (r.metadata?.tableId ?? r.roomId) === parsed.data.tableId);
    const prisma = getPrisma();
    const tableRow = await prisma.pokerTable.findUnique({
      where: { id: parsed.data.tableId },
      select: { name: true, creatorId: true },
    });
    const tableName = room?.metadata?.name ?? tableRow?.name;
    if (!tableName || tableName.trim().length === 0) {
      res.status(409).json({ error: "Table metadata unavailable; cannot process cash-out." });
      return;
    }
    const tableMeta = {
      name: tableName,
      creatorId: room?.metadata?.creatorId ?? tableRow?.creatorId ?? undefined,
    };

    const result = await CashierService.processCashGameCashOut({
      userId: req.user!.id,
      tableId: parsed.data.tableId,
      amountCents: parsed.data.amountCents,
      externalRef: parsed.data.externalRef ?? `cashout_${parsed.data.tableId}_${req.user!.id}`,
      tableMeta,
    });
    res.json(result);
  } catch (err: any) {
    if (err?.message === "INSUFFICIENT_TABLE_BALANCE") {
      res.status(400).json({ error: err.message });
      return;
    }
    if (err?.message === TABLE_NAME_REQUIRED) {
      res.status(409).json({ error: "Table name metadata is required for cash-out." });
      return;
    }
    res.status(500).json({ error: err?.message ?? "Cash-out failed" });
  }
});

