              : where.lessonId?.in == null || where.lessonId.in.includes(a.lessonId)) &&
          (where.status == null || a.status === where.status)
        ));
        return [...rows]
          .sort((a, b) => b.startedAt.getTime() - a.startedAt.getTime())
          .map((row) => ({
